const hex = (bytes) =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');

const traceId = hex(16); // 32 hex chars
const spanId = hex(8); // 16 hex chars

const res = await fetch('/bff/quotes', {
  headers: {
    // W3C Trace Context: <version>-<trace-id>-<parent-id>-<trace-flags>
    // Version is 00 and the sampled bit of trace-flags is set.
    '__BLANK__': `00-${traceId}-${spanId}-__BLANK__`
  }
});

logger.info({ message: 'quotes requested', traceId, status: res.status });

const SAMPLE_RATE = 0.1;

// One trace sampling decision per session, taken once and reused.
const stored = sessionStorage.getItem('trace-sampled');
const sampled = stored !== null ? stored === 'true' : Math.random() < SAMPLE_RATE;
sessionStorage.setItem('trace-sampled', String(sampled));

export function reportSpan(span) {
  if (sampled) beacon('/v1/traces', span);
}

export function reportError(error) {
  if (sampled) beacon('/v1/errors', error);
}

referenceAnswer:
Traces and errors have opposite economics and must not share a sampling gate. Traces are high-volume and statistically redundant — 10% of them still describes latency distributions accurately. Errors are rare, individually meaningful signals: at a 10% gate a bug hitting 30 users shows up as 3, a bug hitting 3 users can show up as 0, and every rate-based alert and release-health number is silently scaled by an unknown factor.

Fix: capture errors at 100% and sample only traces.

```js
export function reportError(error) {
  beacon('/v1/errors', error, { traceId, sampled });
}
```

Control error cost with deduplication by fingerprint, a per-session cap on repeated identical errors, and dropping known third-party noise — not with a probability gate. Keep attaching the trace id so a sampled session's error still links to its trace, and reflect the same decision in the `traceparent` sampled bit.

